/// Parses `300`, `90s`, `5m` or `1h30m` into seconds.
///
/// ```
/// assert_eq!(tidewatch::duration::parse_secs("1h30m"), Ok(5400));
/// ```
pub fn parse_secs(s: &str) -> Result<u64, String> {
    if let Ok(secs) = s.parse() {
        return Ok(secs);
    }
    let bad = || format!("invalid duration {s:?} (try 90s, 5m, 1h30m)");
    let (mut total, mut num, mut digits) = (0u64, 0u64, false);
    for c in s.chars() {
        if let Some(d) = c.to_digit(10) {
            num = num * 10 + u64::from(d);
            digits = true;
        } else if digits && "hms".contains(c) {
            total += num * match c { 'h' => 3600, 'm' => 60, _ => 1 };
            (num, digits) = (0, false);
        } else {
            return Err(bad());
        }
    }
    if digits || total == 0 { Err(bad()) } else { Ok(total) }
}

