// Package ratelimit implements per-key token buckets.
package ratelimit

import (
	"math"
	"net/http"
	"strconv"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

type PerKey struct {
	mu       sync.Mutex
	limiters map[string]*rate.Limiter
	every    time.Duration
	burst    int
}

// New allows n requests per period for each key.
func New(n int, period time.Duration) *PerKey {
	return &PerKey{limiters: map[string]*rate.Limiter{}, every: period / time.Duration(n), burst: n}
}

// Wrap answers 429 with Retry-After once a key is over its limit.
func (p *PerKey) Wrap(next http.HandlerFunc, key func(*http.Request) string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		k := key(r)
		p.mu.Lock()
		l, ok := p.limiters[k]
		if !ok {
			l = rate.NewLimiter(rate.Every(p.every), p.burst)
			p.limiters[k] = l
		}
		p.mu.Unlock()
		res := l.Reserve()
		if d := res.Delay(); d > 0 {
			res.Cancel()
			w.Header().Set("Retry-After", strconv.Itoa(int(math.Ceil(d.Seconds()))))
			http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
			return
		}
		next(w, r)
	}
}

