	"net/http/httptest"
	"testing"
	"time"
)

func TestWrapReturns429WithRetryAfter(t *testing.T) {
	h := New(10, time.Minute).Wrap(func(http.ResponseWriter, *http.Request) {},
		func(*http.Request) string { return "k1" })
	for i := 1; i <= 11; i++ {
		rec := httptest.NewRecorder()
		h(rec, httptest.NewRequest("POST", "/v1/upload", nil))
		if i <= 10 && rec.Code != 200 {
			t.Fatalf("request %d: got %d", i, rec.Code)
		}
		if i == 11 && (rec.Code != 429 || rec.Header().Get("Retry-After") != "6") {
			t.Fatalf("11th: code=%d retry-after=%q", rec.Code, rec.Header().Get("Retry-After"))
		}
	}
}
